#[path="../src/services/concat_video_cancel.rs"]
mod cancellation;

mod support;
#[tokio::test]
async fn authenticated_early_cancel_prevents_analysis_and_refuses_outsiders(){
 use tower::ServiceExt;
 let(state,_root)=support::make_state(true,false).await;std::fs::write(state.storage.join("sources/raw.mkv"),b"never decoded because cancelled").unwrap();assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&serde_json::json!({"id":"raw","filename":"raw.mkv","url":"/files/sources/raw.mkv","mediaType":"video","width":2,"height":2}))).await);let space=state.db.create_space("owner","Cancellation").await.unwrap();let mut document=serde_json::to_value(video_kadr_backend::domain::composition::Composition::new(Default::default())).unwrap();document["sources"]=serde_json::json!({"raw":{"id":"raw","kind":"video","durationTicks":200000,"width":2,"height":2,"hasAudio":false}});document["tracks"]=serde_json::json!([{"kind":"video","id":"videos","name":"Videos","clips":[{"id":"clip","sourceId":"raw","placement":{"timelineStartTick":0,"sourceInTick":0,"sourceOutTick":200000,"speed":1},"transform":video_kadr_backend::domain::composition::TransformSpec::default(),"opacity":{"mode":"constant","value":1},"blendMode":"normal"}]}]);let project=state.db.create_space_composition_project("Cancel",&document,&["raw".into()],"owner",&space.id).await.unwrap();let owner=state.db.register_auth_user("owner","public synthetic password").await.unwrap().unwrap();let outsider=state.db.register_auth_user("outsider","public synthetic password").await.unwrap().unwrap();let app=support::router(state.clone());let endpoint=format!("/api/composition-projects/{}/concat-video-cutout",project.id);let id=uuid::Uuid::new_v4().to_string();let request=|action:&str,token:&str,body:serde_json::Value|axum::http::Request::builder().method("POST").uri(format!("{endpoint}/{action}")).header("content-type","application/json").header("authorization",format!("Bearer {token}")).body(axum::body::Body::from(body.to_string())).unwrap();
 assert_eq!(app.clone().oneshot(request("cancel",&outsider.token,serde_json::json!({"operationId":id}))).await.unwrap().status(),axum::http::StatusCode::FORBIDDEN);assert_eq!(app.clone().oneshot(request("cancel",&owner.token,serde_json::json!({"operationId":"../invalid"}))).await.unwrap().status(),axum::http::StatusCode::BAD_REQUEST);assert_eq!(app.clone().oneshot(request("cancel",&owner.token,serde_json::json!({"operationId":id}))).await.unwrap().status(),axum::http::StatusCode::NO_CONTENT);let response=app.oneshot(request("analyse",&owner.token,serde_json::json!({"clipId":"clip","expectedRevision":project.revision,"operationId":id}))).await.unwrap();assert_eq!(response.status(),axum::http::StatusCode::CONFLICT);assert!(!state.storage.join("concat-video-analysis").exists());
}
